public class JobPosting { private final int id; private final String title,description; private final User postedBy; public JobPosting(int id,String title,String description,User postedBy){this.id=id;this.title=title;this.description=description;this.postedBy=postedBy;} public int getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public User getPostedBy(){return postedBy;} }
